        relTol          0.01;
    }
    pFinal
    {
        $p;
        relTol          0;
    }
    "pcorr.*"
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-5;
        relTol          0;
    }
    "(U|Urel|k|epsilon|omega|nuTilda|R|h|e|T|Yi|b|ft|fu|Su|Xi|ha|hau|ea|eau|tracer)"
