// <provenance>

solvers
{
    "rho.*"
    {
        solver          diagonal;
    }
    p
    {
        solver          GAMG;
        smoother        GaussSeidel;
        tolerance       1e-7;
        relTol          0.01;
    }
    pFinal
    {
        $p;
        relTol          0;
    }
    "pcorr.*"
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-5;
        relTol          0;
    }
    "(U|Urel|k|epsilon|omega|nuTilda|R|h|e|T|Yi|b|ft|fu|Su|Xi|ha|hau|ea|eau|tracer)"
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-7;
        relTol          0.1;
    }
    "(U|Urel|k|epsilon|omega|nuTilda|R|h|e|T|Yi|b|ft|fu|Su|Xi|ha|hau|ea|eau|tracer)Final"
    {
        $U;
        relTol          0;
    }
}

SIMPLE
{
    nNonOrthogonalCorrectors 0;
    residualControl
    {
        p                 1e-4;
        "(U|Urel)"        1e-4;
        "(k|omega)"       1e-4;
        "(h|e)"           1e-4;
    }
}

PIMPLE
{
    nNonOrthogonalCorrectors 0;
    residualControl
    {
        p                 1e-4;
        "(U|Urel)"        1e-4;
        "(k|omega)"       1e-4;
        "(h|e)"           1e-4;
    }
}

relaxationFactors
{
    fields
    {
        p               0.3;
        rho             0.05;
    }
    equations
    {
        "(U|Urel)"      0.7;
        ".*"            0.5;
    }
}

