// <provenance>

solvers
{
    "rho.*"
    {
        solver          diagonal;
    }
    p_rgh
    {
        solver          GAMG;
        smoother        GaussSeidel;
        tolerance       1e-7;
        relTol          0.01;
    }
    p_rghFinal
    {
        $p_rgh;
        relTol          0;
    }
    "pcorr.*"
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-5;
        relTol          0;
    }
    "(U|Urel|k|epsilon|omega|nuTilda|R|h|e|T|Yi|b|ft|fu|Su|Xi|ha|hau|ea|eau|tracer)"
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-7;
        relTol          0.1;
    }
    "(U|Urel|k|epsilon|omega|nuTilda|R|h|e|T|Yi|b|ft|fu|Su|Xi|ha|hau|ea|eau|tracer)Final"
    {
        $U;
        relTol          0;
    }
}

SIMPLE
{
    nNonOrthogonalCorrectors 0;
    residualControl
    {
        p_rgh             1e-4;
        "(U|Urel)"        1e-4;
        "(k|omega)"       1e-4;
        "(h|e)"           1e-4;
    }
}

PIMPLE
{
    nNonOrthogonalCorrectors 0;
    residualControl
    {
        p_rgh             1e-4;
        "(U|Urel)"        1e-4;
        "(k|omega)"       1e-4;
        "(h|e)"           1e-4;
    }
}

relaxationFactors
