FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    location    "system";
    object      controlDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //
// <provenance>

application     foamRun;

solver          incompressibleFluid;

startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         0.0005;
deltaT          0.0001;

writeControl    timeStep;
writeInterval   5;
purgeWrite      0;
writeFormat     ascii;
writePrecision  8;
writeCompression off;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;

adjustTimeStep  yes;
maxCo           0.5;
maxDeltaT       1;

functions
{
    #includeFunc residuals(U, p, k, omega)

    turboForces
    {
        type            forces;
        libs            ("libforces.so");
        writeControl    timeStep;
        writeInterval   1;
        log             yes;
        patches         (walls);
        rho             rhoInf;
        rhoInf          1.225;
        CofR            (0 0 0);
    }

    turboInlet
    {
        type            surfaceFieldValue;
        libs            ("libfieldFunctionObjects.so");
        writeControl    timeStep;
        writeInterval   1;
        writeFields     false;
        log             yes;
        select          patch;
        patch           inlet;
        operation       areaAverage;
        fields          (p U);
    }

    turboFlow
    {
        type            surfaceFieldValue;
        libs            ("libfieldFunctionObjects.so");
        writeControl    timeStep;
        writeInterval   1;
        writeFields     false;
        log             yes;
        select          patch;
        patch           inlet;
        operation       sum;
        fields          (phi);
    }

    turboOutlet
    {
        type            surfaceFieldValue;
        libs            ("libfieldFunctionObjects.so");
        writeControl    timeStep;
        writeInterval   1;
        writeFields     false;
        log             yes;
        select          patch;
        patch           outlet;
        operation       areaAverage;
        fields          (p U);
    }

    #includeFunc yPlus
}

